t.script:
document.addEventListener('DOMContentLoaded', function() {
    var dashboardData = ;

    if (!dashboardData) {
        console.error('No dashboard data available');
        return;
    }

    // Daily Trend Chart
    var trendCtx = document.getElementById('dailyTrendChart');
    if (trendCtx) {
        if (dashboardData.daily_trend) {
            new Chart(trendCtx.getContext('2d'), {
                type: 'line',
                data: {
                    labels: dashboardData.daily_trend.map(function(d) { return d.date; }),
                    datasets: [{
                        label: 'Missing Check-out',
                        data: dashboardData.daily_trend.map(function(d) { return d.missing_checkout; }),
                        borderColor: '#f56565',
                        backgroundColor: 'rgba(245, 101, 101, 0.1)',
                        tension: 0.4,
                        fill: true
                    }, {
                        label: 'Duplicate Check-in',
                        data: dashboardData.daily_trend.map(function(d) { return d.duplicate_checkin; }),
                        borderColor: '#ed8936',
                        backgroundColor: 'rgba(237, 137, 54, 0.1)',
                        tension: 0.4,
                        fill: true
                    }, {
                        label: 'Missing Check-in',
                        data: dashboardData.daily_trend.map(function(d) { return d.missing_checkin; }),
                        borderColor: '#4299e1',
                        backgroundColor: 'rgba(66, 153, 225, 0.1)',
                        tension: 0.4,
                        fill: true
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: true,
                    plugins: {
                        legend: { position: 'bottom' },
                        tooltip: { mode: 'index', intersect: false }
                    },
                    scales: {
                        y: { beginAtZero: true, ticks: { precision: 0 } }
                    }
                }
            });
        }
    }

    // Pie Chart
    var pieCtx = document.getElementById('anomalyTypeChart');
    if (pieCtx) {
        if (dashboardData.summary) {
            new Chart(pieCtx.getContext('2d'), {
                type: 'doughnut',
                data: {
                    labels: ['Missing Check-out', 'Duplicate Check-in', 'Missing Check-in'],
                    datasets: [{
                        data: [
                            dashboardData.summary.missing_checkout,
                            dashboardData.summary.duplicate_checkin,
                            dashboardData.summary.missing_checkin
                        ],
                        backgroundColor: ['#f56565', '#ed8936', '#4299e1'],
                        borderWidth: 2,
                        borderColor: '#fff'
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: true,
                    plugins: {
                        legend: { position: 'bottom' }
                    }
                }
            });
        }
    }

    // ===== LATE CHECK-IN CHARTS =====
    // Late Check-in Trend Chart
    var lateTrendCtx = document.getElementById('lateTrendChart');
    if (lateTrendCtx && dashboardData.late_daily_trend) {
        new Chart(lateTrendCtx.getContext('2d'), {
            type: 'line',
            data: {
                labels: dashboardData.late_daily_trend.map(function(d) { return d.date; }),
                datasets: [{
                    label: 'Late Incidents',
                    data: dashboardData.late_daily_trend.map(function(d) { return d.count; }),
                    borderColor: '#f59e0b',
                    backgroundColor: 'rgba(245, 158, 11, 0.1)',
                    tension: 0.4,
                    fill: true,
                    yAxisID: 'y'
                }, {
                    label: 'Total Late Minutes',
                    data: dashboardData.late_daily_trend.map(function(d) { return d.total_minutes; }),
                    borderColor: '#ef4444',
                    backgroundColor: 'rgba(239, 68, 68, 0.1)',
                    tension: 0.4,
                    fill: true,
                    yAxisID: 'y1'
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: true,
                interaction: {
                    mode: 'index',
                    intersect: false,
                },
                plugins: {
                    legend: { position: 'bottom' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                var label = context.dataset.label || '';
                                if (label) {
                                    label += ': ';
                                }
                                if (context.parsed.y !== null) {
                                    if (context.datasetIndex === 0) {
                                        label += context.parsed.y + ' incidents';
                                    } else {
                                        label += context.parsed.y + ' minutes';
                                    }
                                }
                                return label;
                            }
                        }
                    }
                },
                scales: {
                    y: {
                        type: 'linear',
                        display: true,
                        position: 'left',
                        beginAtZero: true,
                        ticks: { precision: 0 },
                        title: {
                            display: true,
                            text: 'Incidents'
                        }
                    },
                    y1: {
                        type: 'linear',
                        display: true,
                        position: 'right',
                        beginAtZero: true,
                        grid: {
                            drawOnChartArea: false,
                        },
                        title: {
                            display: true,
                            text: 'Minutes'
                        }
                    }
                }
            }
        });
    }

    // Penalty Trend Chart
    var penaltyTrendCtx = document.getElementById('penaltyTrendChart');
    if (penaltyTrendCtx && dashboardData.late_daily_trend) {
        new Chart(penaltyTrendCtx.getContext('2d'), {
            type: 'bar',
            data: {
                labels: dashboardData.late_daily_trend.map(function(d) { return d.date; }),
                datasets: [{
                    label: 'Daily Penalty Amount (৳)',
                    data: dashboardData.late_daily_trend.map(function(d) { return d.total_penalty; }),
                    backgroundColor: 'rgba(239, 68, 68, 0.8)',
                    borderColor: '#dc2626',
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: true,
                plugins: {
                    legend: { position: 'bottom' },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return 'Penalty: ৳' + context.parsed.y.toLocaleString();
                            }
                        }
                    }
                },
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: {
                            callback: function(value) {
                                return '৳' + value.toLocaleString();
                            }
                        }
                    }
                }
            }
        });
    }

    // ===== DATE RANGE FILTER FUNCTIONS =====
    // Set active button on page load based on current range
    setActiveButton();
});

function setActiveButton() {
    // Default to month if nothing specified
    const buttons = document.querySelectorAll('.btn-filter');
    buttons.forEach(btn => btn.classList.remove('active'));
    document.querySelector('.btn-filter[data-range="month"]').classList.add('active');
}

function toggleCustomRange() {
    const customSelector = document.getElementById('customRangeSelector');
    const isVisible = customSelector.style.display !== 'none';

    if (isVisible) {
        customSelector.style.display = 'none';
    } else {
        customSelector.style.display = 'block';
        // Set today's date as default
        const today = new Date().toISOString().split('T')[0];
        document.getElementById('endDate').value = today;

        // Set 30 days ago as start date
        const thirtyDaysAgo = new Date();
        thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
        document.getElementById('startDate').value = thirtyDaysAgo.toISOString().split('T')[0];
    }

    // Update active button
    const buttons = document.querySelectorAll('.btn-filter');
    buttons.forEach(btn => btn.classList.remove('active'));
    document.querySelector('.btn-filter[data-range="custom"]').classList.add('active');
}

function applyDateRange(range) {
    const today = new Date();
    let startDate, endDate;

    switch(range) {
        case 'today':
            startDate = endDate = today.toISOString().split('T')[0];
            break;
        case 'week':
            const weekStart = new Date(today);
            weekStart.setDate(today.getDate() - today.getDay());
            startDate = weekStart.toISOString().split('T')[0];
            endDate = today.toISOString().split('T')[0];
            break;
        case 'month':
            startDate = new Date(today.getFullYear(), today.getMonth(), 1).toISOString().split('T')[0];
            endDate = today.toISOString().split('T')[0];
            break;
        case 'year':
            startDate = new Date(today.getFullYear(), 0, 1).toISOString().split('T')[0];
            endDate = today.toISOString().split('T')[0];
            break;
    }

    // Update active button
    const buttons = document.querySelectorAll('.btn-filter');
    buttons.forEach(btn => btn.classList.remove('active'));
    document.querySelector('.btn-filter[data-range="' + range + '"]').classList.add('active');

    // Hide custom range selector
    document.getElementById('customRangeSelector').style.display = 'none';

    // Reload page with new date range
    window.location.href = '/attendance/anomaly/dashboard?start_date=' + startDate + '&end_date=' + endDate;
}

function applyCustomRange() {
    const startDate = document.getElementById('startDate').value;
    const endDate = document.getElementById('endDate').value;

    if (!startDate || !endDate) {
        alert('Please select both start and end dates');
        return;
    }

    if (startDate > endDate) {
        alert('Start date must be before end date');
        return;
    }

    // Reload page with new date range
    window.location.href = '/attendance/anomaly/dashboard?start_date=' + startDate + '&end_date=' + endDate;
}
